94	void MergeTreeMarksLoader::loadMarks()
95	{
96	    if (mark_cache)
97	    {
98	        auto key = mark_cache->hash(fs::path(data_part_storage->getFullPath()) / mrk_path);
99	        if (save_marks_in_cache)
100	        {
101	            auto callback = [this]{ return loadMarksImpl(); };
102	            marks = mark_cache->getOrSet(key, callback);
103	        }
104	        else
105	        {
106	            marks = mark_cache->get(key);
107	            if (!marks)
108	                marks = loadMarksImpl();
109	        }
110	    }
111	    else
112	        marks = loadMarksImpl();
113	
114	    if (!marks)
115	        throw Exception("Failed to load marks: " + std::string(fs::path(data_part_storage->getFullPath()) / mrk_path), ErrorCodes::LOGICAL_ERROR);
116	}
